import React from "react";
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from "react-router-dom";

import Home from "./pages/Home";
import ArticlesPage from "./pages/ArticlesPage";
import "./styles/navbar.css";

function Navbar() {
  const navigate = useNavigate();
  const token = localStorage.getItem("token");

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("refresh");
    navigate("/login");
  };

  return (
    <nav className="navbar">
      <div className="navbar-left">
        <Link to="/" className="nav-logo">Мій журнал</Link>
        <Link to="/category/news">Новини</Link>
        <Link to="/category/sport">Спорт</Link>
        <Link to="/category/fashion">Мода</Link>
        <Link to="/category/subscriptions">Підписки</Link>
      </div>

      <div className="navbar-right">
        {token ? (
          <button onClick={handleLogout} className="logout-btn">Вийти</button>
        ) : (
          <Link to="/login" className="login-btn">Увійти</Link>
        )}
      </div>
    </nav>
  );
}

function App() {
  return (
    <Router>
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/category/:category" element={<ArticlesPage />} />
      </Routes>
    </Router>
  );
}

export default App;
